import{_ as r,C as l,o as e,c as d,a2 as o,b as n,w as a,a as i,E as u,a3 as p}from"./chunks/framework.BC3NdntU.js";const k=JSON.parse('{"title":"5.4 Vite 与 esbuild","description":"","frontmatter":{},"headers":[],"relativePath":"卷五-构建与工程化/5.4-Vite与esbuild.md","filePath":"卷五-构建与工程化/5.4-Vite与esbuild.md","lastUpdated":1788855682000}'),b={name:"卷五-构建与工程化/5.4-Vite与esbuild.md"};function h(c,t,g,E,q,_){const s=l("Mermaid");return e(),d("div",null,[t[1]||(t[1]=o('<h1 id="_5-4-vite-与-esbuild" tabindex="-1">5.4 Vite 与 esbuild <a class="header-anchor" href="#_5-4-vite-与-esbuild" aria-label="Permalink to &quot;5.4 Vite 与 esbuild&quot;">​</a></h1><blockquote><p>卷:卷五 · 构建与工程化 阅读时间:25min</p></blockquote><hr><h2 id="引言-vite-为什么-一启动就能开发" tabindex="-1">引言:Vite 为什么&quot;一启动就能开发&quot; <a class="header-anchor" href="#引言-vite-为什么-一启动就能开发" aria-label="Permalink to &quot;引言:Vite 为什么&quot;一启动就能开发&quot;&quot;">​</a></h2><p>webpack 思路是&quot;先全量打包再启动&quot;,越大越慢;Vite 反其道:<strong>开发期不打包</strong>,靠原生 ESM + 按需编译,快得惊人。深挖要懂<strong>双引擎的取舍逻辑</strong>。</p><hr><h2 id="一、双引擎-开发用-esbuild-构建用-rollup-一图" tabindex="-1">一、双引擎:开发用 esbuild,构建用 Rollup(一图) <a class="header-anchor" href="#一、双引擎-开发用-esbuild-构建用-rollup-一图" aria-label="Permalink to &quot;一、双引擎:开发用 esbuild,构建用 Rollup(一图)&quot;">​</a></h2>',7)),(e(),n(p,null,{default:a(()=>[u(s,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20subgraph%20%E5%BC%80%E5%8F%91%20dev%0A%20%20%20%20A%5Bnative%20ESM%20%E5%8A%A0%E8%BD%BD%5D%20--%3E%20B%5B%E8%AF%B7%E6%B1%82%E5%88%B0%E5%93%AA%E4%B8%AA%E6%A8%A1%E5%9D%97%5D%0A%20%20%20%20B%20--%3E%20C%5Besbuild%20%E7%9E%AC%E7%BC%96%E8%AF%91%E8%AF%A5%E6%A8%A1%E5%9D%97%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20%E6%9E%84%E5%BB%BA%20build%0A%20%20%20%20D%5B%E5%85%A8%E9%87%8F%E4%BE%9D%E8%B5%96%E5%88%86%E6%9E%90%5D%20--%3E%20E%5BRollup%20%E6%89%93%E5%8C%85%5D%0A%20%20%20%20E%20--%3E%20F%5B%E4%BA%A7%E7%89%A9%20%E6%A0%91%E6%91%87%20%E5%88%86%E5%8C%85%5D%0A%20%20%20%20end%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[i(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=o(`<table tabindex="0"><thead><tr><th>阶段</th><th>引擎</th><th>为什么</th></tr></thead><tbody><tr><td>开发</td><td>esbuild + 原生 ESM</td><td>快,不打包,按需</td></tr><tr><td>构建</td><td><strong>Rollup</strong></td><td>树摇好、产物干净</td></tr></tbody></table><p><strong>为什么开发用 esbuild、构建用 Rollup(深层)?</strong> 开发求&quot;<strong>最快</strong>&quot;(启动/HMR),esbuild 极快且只需&quot;能跑&quot;;构建求&quot;<strong>最优产物</strong>&quot;(极致树摇、分包控制、兼容),Rollup 更成熟稳定。<strong>&quot;开发求速、构建求优&quot;</strong> 的分工。</p><hr><h2 id="二、三个关键机制" tabindex="-1">二、三个关键机制 <a class="header-anchor" href="#二、三个关键机制" aria-label="Permalink to &quot;二、三个关键机制&quot;">​</a></h2><h3 id="_1-依赖预构建" tabindex="-1">1. 依赖预构建 <a class="header-anchor" href="#_1-依赖预构建" aria-label="Permalink to &quot;1. 依赖预构建&quot;">​</a></h3><p><code>node_modules</code> 里的库(CJS、海量小文件)按原生 ESM 逐个请求会爆炸。Vite 启动时用 esbuild <strong>预构建</strong>:</p><ul><li>CJS → ESM</li><li>分散小文件 → 合并成单个(如 <code>lodash-es</code> 几百个模块 → 一个)</li></ul><h3 id="_2-按需编译-秒级-hmr" tabindex="-1">2. 按需编译 + 秒级 HMR <a class="header-anchor" href="#_2-按需编译-秒级-hmr" aria-label="Permalink to &quot;2. 按需编译 + 秒级 HMR&quot;">​</a></h3><p>浏览器<strong>请求到哪个文件</strong>,esbuild 才现编译哪个;改哪个文件,<strong>只失效那一条链</strong>,毫秒替换、状态不丢。</p><h3 id="_3-构建走-rollup" tabindex="-1">3. 构建走 Rollup <a class="header-anchor" href="#_3-构建走-rollup" aria-label="Permalink to &quot;3. 构建走 Rollup&quot;">​</a></h3><p>生产求最优产物,交给 Rollup(5.5),<code>rollupOptions</code> 可透传定制。</p><hr><h2 id="三、vite-vs-webpack-选型" tabindex="-1">三、Vite vs webpack(选型) <a class="header-anchor" href="#三、vite-vs-webpack-选型" aria-label="Permalink to &quot;三、Vite vs webpack(选型)&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Vite</th><th>webpack</th></tr></thead><tbody><tr><td>开发启动</td><td><strong>秒级</strong></td><td>秒到分钟</td></tr><tr><td>HMR</td><td>极快(按需失效)</td><td>随项目变大</td></tr><tr><td>引擎</td><td>esbuild(dev)+ Rollup(build)</td><td>tapable 体系</td></tr><tr><td>生态</td><td>成长中</td><td><strong>最全</strong></td></tr></tbody></table><blockquote><p>新项目默认 Vite;存量复杂项目 webpack;Rolldown 正成 Vite 未来构建内核(5.6)。</p></blockquote><hr><h2 id="四、小结" tabindex="-1">四、小结 <a class="header-anchor" href="#四、小结" aria-label="Permalink to &quot;四、小结&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Vite 双引擎:dev esbuild(预构建+不打包+按需),build Rollup</span></span>
<span class="line"><span>三机制:依赖预构建(CJS→ESM,合并)/ 按需编译+秒级 HMR / 构建 Rollup</span></span>
<span class="line"><span>分工本质:开发求速(esbuild),构建求优(Rollup)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><hr><h2 id="五、面试题" tabindex="-1">五、面试题 <a class="header-anchor" href="#五、面试题" aria-label="Permalink to &quot;五、面试题&quot;">​</a></h2><p><strong>Q1:Vite 为什么开发&quot;几乎秒开&quot;,webpack 却越来越慢?</strong></p><p>Vite 开发期<strong>不打包</strong>:原生 ESM,请求到哪个模块才用 esbuild 现编译哪个(按需);webpack 要<strong>全量打包</strong>再启动。这是&quot;按需 vs 全量&quot;的差异。</p><p><strong>Q2:Vite 的&quot;依赖预构建&quot;解决什么问题?</strong></p><p><code>node_modules</code> 里的库常是 CJS、拆成海量小文件。预构建用 esbuild 把它们① <strong>CJS→ESM</strong>、② <strong>合并成大模块</strong>,避免浏览器成千上万请求,兼顾&quot;不打包&quot;与&quot;加载效率&quot;。</p><p><strong>Q3:为什么 Vite 开发用 esbuild、构建用 Rollup?</strong></p><p>开发求<strong>最快</strong>(esbuild 极快);构建求<strong>最优产物</strong>(Rollup 树摇/分包更成熟)。&quot;开发求速、构建求优&quot;。</p><p><strong>Q4:Vite 的 HMR 为什么比 webpack 快?</strong></p><p>Vite 的 HMR 是&quot;<strong>按需失效</strong>&quot;:只让改动的模块链失效重载,且不打包、只转译单文件;webpack 要重新构建受影响的 chunk。所以 Vite HMR 近乎瞬时、状态不丢。</p><p><strong>Q5:一个 Vite 项目冷启动时,那行&quot;预构建依赖&quot;日志在干什么?</strong></p><p>在启动时用 esbuild 对 <code>node_modules</code> 做<strong>预构建</strong>(CJS→ESM、合并小模块),结果缓存起来,让后续按需加载高效。改依赖后会自动重新预构建。</p><p><strong>Q6:Vite 能完全替代 webpack 吗?什么情况仍用 webpack?</strong></p><p>大多数新项目可替代;但<strong>深度定制的复杂存量项目、特殊 loader/插件生态、兼容性要求高</strong>的场景,webpack 生态更全更稳,迁移成本高,仍用 webpack。</p><hr><p>📎 参考:Vite 官方文档、esbuild 官网、Rollup 文档</p>`,34))])}const A=r(b,[["render",h]]);export{k as __pageData,A as default};
